def n_queens(n):
    # Initialize a 2D list to represent the chessboard
    board = [["."] * n for _ in range(n)]

    # Function to place a queen in a row and check if it's safe
    def is_safe(row, col):
        for i in range(row):
            if board[i][col] == "Q":
                return False
            diff = col - i
            if board[i][col - diff] == "Q":
                return False
            if board[i][col + diff] == "Q":
                return False
        return True

    # Function to recursively place queens on the board
    def place_queen(row):
        if row == n:
            # If we've reached the end of the board, yield the current configuration
            yield "".join("".join(row_) for row_ in board)
        else:
            # Try placing a queen in each column
            for col in range(n):
                if is_safe(row, col):
                    board[row][col] = "Q"
                    yield from place_queen(row + 1)
                    board[row][col] = "."

    # Generate all possible configurations and return them
    return list(n_queens(n))
```

